public TreeNode? BuildTree(int[] preorder, int[] inorder)
{
    var map = new Dictionary<int, int>();
    for (int i = 0; i < inorder.Length; i++) map[inorder[i]] = i;
    return Build(0, 0, inorder.Length - 1);

    TreeNode? Build(int preStart, int inStart, int inEnd)
    {
        if (preStart >= preorder.Length || inStart > inEnd) return null;
        TreeNode root = new TreeNode(preorder[preStart]);
        int inRoot = map[preorder[preStart]];
        root.Left = Build(preStart + 1, inStart, inRoot - 1);
        root.Right = Build(preStart + 1 + (inRoot - inStart), inRoot + 1, inEnd);
        return root;
    }
}
